(function(root){'use strict';root.RPSGTLearningLibrary={"VERSION":"2026-08-14-v2-learning-library-1","source":"RPSGTv2.2026_1.html","counts":{"flashcards":312,"glossary":258,"mathLessons":20,"mathQuestions":100},"flashcards":[{"id":"builtin:v2-fc-fio2","legacyId":"fc-fio2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"FiO2","back":"Fraction of inspired oxygen. It is the oxygen concentration being inhaled, written as a decimal or percent, such as 0.21 or 21%.","memoryClue":"FiO2 is what goes in; SpO2 is what the pulse ox estimates in the patient.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-spo2","legacyId":"fc-spo2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"SpO2","back":"Peripheral oxygen saturation estimated by pulse oximetry. Unit: percent (%).","memoryClue":"SpO2 does not prove CO2 removal is adequate.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-sao2","legacyId":"fc-sao2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"SaO2","back":"Arterial oxygen saturation, commonly from arterial blood/co-oximetry context. Unit: percent (%).","memoryClue":"SaO2 is saturation, not PaO2 pressure.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-pao2","legacyId":"fc-pao2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"PaO2","back":"Arterial partial pressure of oxygen. Unit: mmHg.","memoryClue":"Lowercase a means arterial; PaO2 is not a percent.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-paao2","legacyId":"fc-paao2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"PAO2","back":"Alveolar partial pressure of oxygen. Unit: mmHg.","memoryClue":"Capital A means alveolar; lowercase a means arterial.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-paco2","legacyId":"fc-paco2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"PaCO2","back":"Arterial partial pressure of carbon dioxide. Unit: mmHg. It is a key blood-gas clue for ventilation.","memoryClue":"CO2 tells ventilation; normal SpO2 may not reveal CO2 retention.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-etco2","legacyId":"fc-etco2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"EtCO2 / PETCO2","back":"End-tidal carbon dioxide at the end of exhalation, measured by capnography. Unit: commonly mmHg.","memoryClue":"Mouth breathing, leaks, oxygen flow, and cannula problems can distort EtCO2.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-tcco2","legacyId":"fc-tcco2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"TcCO2 / PtcCO2","back":"Transcutaneous carbon dioxide estimated through a heated skin sensor. Unit: mmHg. Best understood as a trend.","memoryClue":"TcCO2 responds slower than breath-by-breath EtCO2.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-tco2","legacyId":"fc-tco2","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"TcO2 / PtcO2","back":"Transcutaneous oxygen estimated through the skin. Unit: mmHg.","memoryClue":"TcO2 is a pressure estimate, not SpO2 percent.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-hypercapnia","legacyId":"fc-hypercapnia","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Hypercapnia","back":"Elevated carbon dioxide, usually reflected by increased PaCO2/TcCO2/EtCO2 in mmHg context.","memoryClue":"Hypercapnia is a ventilation problem, not simply low oxygen saturation.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-hypocapnia","legacyId":"fc-hypocapnia","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Hypocapnia","back":"Low carbon dioxide, often from excessive ventilation relative to metabolic need.","memoryClue":"Do not confuse low CO2 with hypoxemia.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-hypoxemia","legacyId":"fc-hypoxemia","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Hypoxemia","back":"Low oxygen in the blood; may be reflected by low PaO2 or low oxygen saturation depending on the measure.","memoryClue":"Hypoxemia is not the same as hypoventilation, although they can occur together.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-hypoxia","legacyId":"fc-hypoxia","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Hypoxia","back":"Inadequate oxygen at tissue level.","memoryClue":"Hypoxia and hypoxemia are related but not identical terms.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-hypoventilation","legacyId":"fc-hypoventilation","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Hypoventilation","back":"Inadequate alveolar ventilation causing CO2 retention; CO2 values rise.","memoryClue":"SpO2 can look acceptable while CO2 is high, especially with supplemental oxygen.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-hyperventilation","legacyId":"fc-hyperventilation","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Hyperventilation","back":"Ventilation greater than metabolic need, commonly lowering CO2.","memoryClue":"Do not equate fast breathing alone with effective ventilation.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-mmHg","legacyId":"fc-mmHg","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"mmHg","back":"Millimeters of mercury. Used for blood pressure, ABG partial pressures, PaO2, PaCO2, EtCO2, and TcCO2.","memoryClue":"Do not use mmHg for PAP pressures.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-cmh2o","legacyId":"fc-cmh2o","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"cm H2O","back":"Centimeters of water. Used for CPAP, EPAP, IPAP, BPAP, and pressure support.","memoryClue":"PAP pressure is not measured in mmHg.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-lpm","legacyId":"fc-lpm","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"L/min or lpm","back":"Liters per minute. Used for oxygen flow from wall oxygen, tank/cylinder, liquid oxygen source, or concentrator.","memoryClue":"O2 flow is not cm H2O and not percent.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-percent","legacyId":"fc-percent","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"%","back":"Percent. Used for oxygen saturation values such as SpO2/SaO2 and for FiO2 when written as a percent.","memoryClue":"Percent is not mmHg or L/min.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-o2-source","legacyId":"fc-o2-source","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Oxygen source","back":"Where oxygen comes from: wall oxygen, cylinder/tank, liquid oxygen, or oxygen concentrator.","memoryClue":"The source is not the flow dose and not the patient's SpO2.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-o2-device","legacyId":"fc-o2-device","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Oxygen delivery device","back":"The interface or pathway: nasal cannula, mask, oxygen tubing, or PAP bleed-in connector.","memoryClue":"Do not document the device as the oxygen dose.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-o2-dose","legacyId":"fc-o2-dose","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Oxygen dose/flow","back":"The ordered or delivered oxygen amount, commonly charted in L/min or FiO2 depending on setup.","memoryClue":"Dose/flow is not SpO2, which is the patient response.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-o2-measure","legacyId":"fc-o2-measure","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Patient oxygen measurement","back":"Values such as SpO2, SaO2, or PaO2 that describe patient oxygenation.","memoryClue":"A patient measurement is not the same as the source or device.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-concentrator","legacyId":"fc-concentrator","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Oxygen concentrator","back":"A device that concentrates oxygen from room air for low-flow oxygen delivery.","memoryClue":"Concentrator is correct; condenser is a distractor.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-cylinder","legacyId":"fc-cylinder","custom":false,"category":"Oxygen, CO2 & Units","topic":"Oxygen, CO2 & Units","front":"Oxygen cylinder / tank","back":"A compressed oxygen source.","memoryClue":"A tank/cylinder is a source; flow is still documented in L/min.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-bleedin","legacyId":"fc-bleedin","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"O2 bleed-in connector","back":"A connector/adapter that adds supplemental oxygen into the PAP circuit.","memoryClue":"Oxygen bleed-in does not change the CPAP pressure unit.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-cpap","legacyId":"fc-cpap","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"CPAP","back":"Continuous positive airway pressure. One continuous pressure used to help splint the airway. Unit: cm H2O.","memoryClue":"CPAP is not oxygen flow and not mmHg.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-bpap","legacyId":"fc-bpap","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"BPAP / bilevel PAP","back":"Bilevel positive airway pressure with separate inspiratory and expiratory pressure settings.","memoryClue":"BPAP is not just 'higher CPAP'; it has IPAP and EPAP.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ipap","legacyId":"fc-ipap","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"IPAP","back":"Inspiratory positive airway pressure. Unit: cm H2O.","memoryClue":"IPAP is not oxygen flow.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-epap","legacyId":"fc-epap","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"EPAP","back":"Expiratory positive airway pressure. Unit: cm H2O.","memoryClue":"EPAP supports airway patency during exhalation; it is not EtCO2.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ps","legacyId":"fc-ps","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Pressure support","back":"Pressure support = IPAP - EPAP. Unit: cm H2O.","memoryClue":"Pressure support is not L/min oxygen flow.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-asv","legacyId":"fc-asv","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"ASV","back":"Adaptive servo-ventilation, a PAP mode that varies inspiratory support in response to breathing pattern.","memoryClue":"Know the concept; avoid assuming it is appropriate for every central breathing case.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-avaps","legacyId":"fc-avaps","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"AVAPS / VAPS","back":"Average volume-assured pressure support / volume-assured pressure support; adjusts pressure support to target ventilation parameters.","memoryClue":"Do not confuse pressure support with oxygen flow.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-st","legacyId":"fc-st","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"BPAP S/T","back":"Bilevel PAP with spontaneous/timed backup support.","memoryClue":"The timed backup relates to breaths, not oxygen saturation percent.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ramp","legacyId":"fc-ramp","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"Ramp","back":"A PAP comfort feature that starts at a lower pressure and gradually increases.","memoryClue":"Ramp is comfort support; it is not treatment pressure once therapeutic pressure is reached.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-leak","legacyId":"fc-leak","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"Leak","back":"Unintended air escaping from mask or mouth that can distort PAP signals and reduce therapy effectiveness.","memoryClue":"Fix leak before assuming pressure is inadequate.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-rainout","legacyId":"fc-rainout","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"Rainout","back":"Condensation/water collecting in PAP tubing or mask.","memoryClue":"Rainout is humidity/temperature management, not oxygen desaturation by itself.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-humidification","legacyId":"fc-humidification","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"Humidification","back":"Moisture added to PAP airflow to reduce dryness and improve comfort.","memoryClue":"Too much humidity/temperature mismatch can contribute to rainout.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-fullface","legacyId":"fc-fullface","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"Full-face / oronasal PAP mask","back":"PAP interface that covers the nose and mouth.","memoryClue":"Do not assume full-face mask means higher therapeutic pressure is automatically needed.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-nasal-mask","legacyId":"fc-nasal-mask","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"Nasal mask","back":"PAP interface that covers the nose but not the mouth.","memoryClue":"Mouth leak can reduce effective therapy with a nasal-only interface.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-nasal-pillows","legacyId":"fc-nasal-pillows","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"Nasal pillows","back":"Small PAP interface cushions that seal at the nostrils.","memoryClue":"Interface size and leak matter more than assuming one style is always best.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-chinstrap","legacyId":"fc-chinstrap","custom":false,"category":"PAP & Oxygen Therapy","topic":"PAP & Oxygen Therapy","front":"Chin strap","back":"Accessory sometimes used to reduce mouth opening/mouth leak with nasal PAP.","memoryClue":"A chin strap does not replace correct mask fit or troubleshooting.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ahi","legacyId":"fc-ahi","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"AHI","back":"Apnea-Hypopnea Index = (apneas + hypopneas) / total sleep time in hours.","memoryClue":"AHI uses TST in hours, not total recording time.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-rdi","legacyId":"fc-rdi","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"RDI","back":"Respiratory Disturbance Index = (apneas + hypopneas + RERAs) / total sleep time in hours when RERAs are included.","memoryClue":"RDI can be higher than AHI because it may include RERAs.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-rei","legacyId":"fc-rei","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"REI","back":"Respiratory Event Index = respiratory events / monitoring or recording time in hours, commonly used in HSAT context.","memoryClue":"REI denominator differs from PSG AHI denominator.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-arousal-index","legacyId":"fc-arousal-index","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Arousal index","back":"Arousals / total sleep time in hours.","memoryClue":"Convert TST to hours before dividing.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-plmi","legacyId":"fc-plmi","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"PLMI","back":"Periodic limb movements / total sleep time in hours.","memoryClue":"PLMI is a frequency index, not the number of movements alone.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-odi","legacyId":"fc-odi","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"ODI","back":"Oxygen Desaturation Index = qualifying desaturations / hours of sleep or monitoring time depending on context/reporting convention.","memoryClue":"Know which denominator the question specifies.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-se","legacyId":"fc-se","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Sleep efficiency","back":"Sleep efficiency = total sleep time / total recording time (or time in bed, per reporting convention) x 100.","memoryClue":"Read the denominator given by the question or reporting standard.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-sol","legacyId":"fc-sol","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Sleep onset latency","back":"Time from lights out / recording start to sleep onset, depending on the defined reporting convention.","memoryClue":"Know the start point and the first sleep epoch used by the question.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-rem-latency","legacyId":"fc-rem-latency","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"REM latency","back":"Time from sleep onset to the first epoch of REM sleep.","memoryClue":"Start at sleep onset, not lights out.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-tst","legacyId":"fc-tst","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Total sleep time (TST)","back":"The total minutes spent asleep across scored sleep stages.","memoryClue":"TST excludes wake time.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-waso","legacyId":"fc-waso","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"WASO","back":"Wake after sleep onset: wake time occurring after initial sleep onset and before final awakening/end of recording convention.","memoryClue":"WASO is not sleep-onset latency.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-stagepct","legacyId":"fc-stagepct","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Sleep stage percentage","back":"Stage minutes / total sleep time x 100.","memoryClue":"Use TST as denominator for sleep-stage percentages.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-trt","legacyId":"fc-trt","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Total recording time (TRT)","back":"Duration of the recording period used by the report; often lights on minus lights out when those define the recording interval.","memoryClue":"TRT includes wake and sleep.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-time-hours","legacyId":"fc-time-hours","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Minutes to hours conversion","back":"Minutes / 60 = hours.","memoryClue":"Most sleep indexes require hours in the denominator.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-epochs","legacyId":"fc-epochs","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Standard PSG epoch","back":"A standard PSG scoring epoch is 30 seconds.","memoryClue":"Two epochs equal one minute.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ohms-law","legacyId":"fc-ohms-law","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Ohm's law","back":"V = I x R. Rearrangements: I = V/R and R = V/I.","memoryClue":"Track the units before calculating.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-frequency","legacyId":"fc-frequency","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Frequency","back":"Frequency (Hz) = cycles / seconds.","memoryClue":"Hz means cycles per second.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-sensitivity","legacyId":"fc-sensitivity","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Sensitivity","back":"A display relationship describing voltage per unit of deflection, commonly expressed in µV/mm in sleep technology contexts.","memoryClue":"Sensitivity changes display size; it does not change the patient's true signal.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ten20","legacyId":"fc-ten20","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"10-20 calculation","back":"Head measurement distances are divided into percentages to locate standard electrode positions.","memoryClue":"Use the specific measurement and percentage the problem gives.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ps-math","legacyId":"fc-ps-math","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Pressure support calculation","back":"Pressure support = IPAP - EPAP.","memoryClue":"Subtract EPAP from IPAP, both in cm H2O.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-o2-flow-math","legacyId":"fc-o2-flow-math","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Oxygen flow calculation context","back":"Oxygen flow is commonly documented in L/min; follow the ordered/titration protocol and the specific arithmetic provided by the question.","memoryClue":"Do not convert oxygen flow into PAP pressure units.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-cm-vs-mm","legacyId":"fc-cm-vs-mm","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"cm H2O vs mmHg","back":"cm H2O is used for PAP pressure; mmHg is used for blood gases and blood pressure contexts.","memoryClue":"Units can identify the correct answer before you calculate.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-odiv","legacyId":"fc-odiv","custom":false,"category":"Report Math & Indexes","topic":"Report Math & Indexes","front":"Index denominator trap","back":"Before calculating AHI, RDI, PLMI, arousal index, or stage %, identify the correct denominator and convert units first.","memoryClue":"The denominator is often the exam trap.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-eeg","legacyId":"fc-eeg","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"EEG","back":"Electroencephalogram: records brain electrical activity from scalp electrodes.","memoryClue":"EEG is voltage over time, not cerebral blood flow.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-eog","legacyId":"fc-eog","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"EOG","back":"Electrooculogram: records eye movements using the standing corneo-retinal potential.","memoryClue":"EOG channels help identify slow eye movements and rapid eye movements.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-emg","legacyId":"fc-emg","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"EMG","back":"Electromyogram: records electrical activity from muscle.","memoryClue":"Chin EMG helps staging; limb EMG supports limb-movement scoring.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ecg","legacyId":"fc-ecg","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"ECG / EKG","back":"Electrocardiogram: records cardiac electrical activity.","memoryClue":"ECG is a signal channel; rhythm interpretation requires clean signal and clinical context.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-bipolar","legacyId":"fc-bipolar","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Bipolar derivation","back":"A channel formed by comparing the voltage at one electrode input with the voltage at another electrode input.","memoryClue":"The amplifier displays the difference between inputs.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-referential","legacyId":"fc-referential","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Referential derivation","back":"An active electrode is compared with a reference electrode or reference site.","memoryClue":"A bad reference can contaminate multiple channels that share it.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-common-mode","legacyId":"fc-common-mode","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Common-mode signal","back":"A signal or noise component present similarly at both amplifier inputs.","memoryClue":"Differential amplifiers are designed to reject common-mode signals.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-cmrr","legacyId":"fc-cmrr","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Common-mode rejection ratio (CMRR)","back":"A measure of how well a differential amplifier rejects signals common to both inputs relative to differential signals.","memoryClue":"Higher CMRR means better rejection of shared noise.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-impedance","legacyId":"fc-impedance","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Electrode impedance","back":"Opposition to alternating current at the electrode-skin interface, measured in ohms (Ω), commonly kΩ in PSG setup checks.","memoryClue":"High or unequal impedance can worsen signal quality and artifact.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-salt-bridge","legacyId":"fc-salt-bridge","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Salt bridge","back":"Conductive paste, sweat, or moisture electrically connects two electrodes, reducing the true difference between them.","memoryClue":"Separate and clean the electrodes; changing sensitivity does not fix a bridge.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-electrode-pop","legacyId":"fc-electrode-pop","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Electrode pop","back":"Abrupt transient artifact from unstable electrode contact or electrode-skin interface changes.","memoryClue":"Check electrode integrity before labeling a sudden spike as physiology.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-60hz","legacyId":"fc-60hz","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"60-Hz artifact","back":"Regular high-frequency electrical interference commonly related to power sources, poor grounding, or poor electrode contact.","memoryClue":"Find the source before relying on a notch filter.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ground-loop","legacyId":"fc-ground-loop","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Ground loop","back":"Electrical noise created by multiple grounding paths or differences in electrical potential between connected equipment.","memoryClue":"Do not defeat safety grounding. Follow facility/equipment safety procedures.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-diff-amp","legacyId":"fc-diff-amp","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Differential amplifier","back":"Amplifies the voltage difference between its two inputs while rejecting signals common to both.","memoryClue":"If the same signal is present at both inputs, ideal differential output is small.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-gain","legacyId":"fc-gain","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Gain","back":"The ratio of output signal amplitude to input signal amplitude in an amplifier system.","memoryClue":"Gain is not the same thing as filter setting.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-lff","legacyId":"fc-lff","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Low-frequency filter (LFF)","back":"Attenuates frequencies below the selected cutoff.","memoryClue":"Raising the LFF removes more slow activity and can distort slow waves.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-hff","legacyId":"fc-hff","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"High-frequency filter (HFF)","back":"Attenuates frequencies above the selected cutoff.","memoryClue":"Lowering the HFF removes more fast activity and can round sharp waveforms.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-notch","legacyId":"fc-notch","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Notch filter","back":"A narrow filter designed to attenuate a specific frequency, commonly line-frequency interference.","memoryClue":"A notch filter may hide noise without correcting the underlying technical problem.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-sampling","legacyId":"fc-sampling","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Sampling rate","back":"How many times per second a digital system measures the signal, expressed in samples/second or Hz.","memoryClue":"Sampling rate must be high enough to represent the signal frequencies of interest.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-nyquist","legacyId":"fc-nyquist","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Nyquist concept","back":"To represent a frequency without aliasing, sampling must exceed twice the highest frequency of interest.","memoryClue":"Sampling too slowly can create false lower-frequency patterns.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-aliasing","legacyId":"fc-aliasing","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Aliasing","back":"Distortion caused when a signal is sampled too slowly, making higher-frequency content appear as false lower-frequency activity.","memoryClue":"Aliasing is a sampling problem, not a physiologic rhythm.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-calibration","legacyId":"fc-calibration","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Calibration signal","back":"Known signal used to verify channel response, amplitude, polarity, and system function.","memoryClue":"Calibration checks the recording system; biocals check physiologic responses/channels.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-biocals","legacyId":"fc-biocals","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Biocalibrations","back":"Patient-performed maneuvers used to verify physiologic channel response before or after a study.","memoryClue":"Examples include eye movements, blinking, teeth clenching, breathing maneuvers, and leg movement depending on protocol.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-polarity","legacyId":"fc-polarity","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Signal polarity","back":"Direction of waveform deflection depends on the voltage relationship between amplifier inputs and the display convention.","memoryClue":"Know the derivation before assuming a deflection is positive or negative physiology.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-amplitude","legacyId":"fc-amplitude","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Amplitude","back":"Size of a signal, commonly measured in microvolts (µV) for EEG/EOG/EMG contexts.","memoryClue":"Amplitude is not frequency.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-frequency-unit","legacyId":"fc-frequency-unit","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Hertz (Hz)","back":"Cycles per second, the unit of frequency.","memoryClue":"Hz describes how fast a waveform repeats, not how tall it is.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-dc","legacyId":"fc-dc","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"DC signal","back":"Direct-current or near-zero-frequency component that can represent very slow shifts or sensor baselines depending on the channel.","memoryClue":"Do not assume every channel is AC-coupled the same way.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-ac","legacyId":"fc-ac","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"AC signal","back":"Alternating signal component that changes over time around a baseline.","memoryClue":"Many physiologic signals are recorded as changing voltage over time.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-artifact","legacyId":"fc-artifact","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Artifact","back":"Recorded signal that does not represent the intended physiologic source.","memoryClue":"Troubleshoot signal origin before scoring physiology.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-motion-artifact","legacyId":"fc-motion-artifact","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Movement artifact","back":"Signal distortion caused by patient or equipment movement rather than the target physiology.","memoryClue":"Look for simultaneous changes across channels and video/body movement context.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-cardio-ballistic","legacyId":"fc-cardio-ballistic","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Cardioballistic artifact","back":"Pulse-related mechanical artifact transmitted into another channel, often repeating with the ECG/pulse.","memoryClue":"If artifact timing tracks the QRS/pulse, think cardioballistic contamination.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-perspiration","legacyId":"fc-perspiration","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Sweat / perspiration artifact","back":"Very slow baseline drift from changes in skin potentials associated with sweating.","memoryClue":"It can resemble slow EEG shifts but often affects multiple channels and follows sweating conditions.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-snore-artifact","legacyId":"fc-snore-artifact","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Snore artifact contamination","back":"Vibration from snoring may appear in nearby channels, including airflow or EMG signals.","memoryClue":"Use timing and channel distribution to separate vibration artifact from true physiology.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-respiratory-artifact","legacyId":"fc-respiratory-artifact","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Respiratory artifact","back":"Slow rhythmic contamination of a non-respiratory channel caused by breathing movement or electrode/cable motion.","memoryClue":"Compare with effort channels before scoring it as EEG/EOG activity.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-reference-problem","legacyId":"fc-reference-problem","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Reference electrode problem","back":"Poor reference contact can contaminate every channel that shares that reference.","memoryClue":"If several same-reference channels look bad, inspect the common reference first.","sourceContext":"RPSGT V2 learning library"},{"id":"builtin:v2-fc-leakage-current","legacyId":"fc-leakage-current","custom":false,"category":"Signals, Filters & Instrumentation","topic":"Signals, Filters & Instrumentation","front":"Leakage current","back":"Unintended small electrical current that may flow through equipment pathways; controlled through equipment design, testing, and safety procedures.","memoryClue":"Follow facility policy and biomedical/equipment safety procedures; do not improvise electrical safety fixes.","sourceContext":"RPSGT V2 learning library"}],"glossary":[{"term":"AHI","category":"Respiratory Metrics","plain":"Apnea-hypopnea index: apneas + hypopneas per hour of sleep.","why":"Central summary of obstructive sleep apnea severity when interpreted in context.","confusion":"Do not confuse with RDI, which may include RERAs.","linked":["Scoring","Respiratory","Reports"]},{"term":"RDI","category":"Respiratory Metrics","plain":"Respiratory disturbance index: usually apneas + hypopneas + RERAs per hour of sleep.","why":"Can be higher than AHI because it may include RERAs.","confusion":"Do not assume AHI and RDI are interchangeable.","linked":["Scoring","Respiratory","Reports"]},{"term":"REI","category":"Respiratory Metrics","plain":"Respiratory event index: respiratory events per hour of monitoring/recording time in HSAT-style reporting.","why":"Used when EEG-based total sleep time is unavailable.","confusion":"REI denominator differs from PSG AHI denominator.","linked":["HSAT","Reports"]},{"term":"RERA","category":"Respiratory Events","plain":"Respiratory effort-related arousal: a breathing sequence with increased effort or flattening that leads to arousal but does not meet apnea/hypopnea criteria.","why":"Helps explain sleep fragmentation when AHI alone may look modest.","confusion":"RERA is not simply any arousal with snoring.","linked":["Scoring","Respiratory"]},{"term":"OAI","category":"Respiratory Metrics","plain":"Obstructive apnea index: obstructive apneas per hour of sleep.","why":"Breaks the AHI into event type.","confusion":"Not the same as overall AHI.","linked":["Scoring","Reports"]},{"term":"CAI","category":"Respiratory Metrics","plain":"Central apnea index: central apneas per hour of sleep.","why":"Helps quantify central events separately from obstructive events.","confusion":"Do not use CAI for mixed apneas.","linked":["Scoring","Reports"]},{"term":"MAI","category":"Respiratory Metrics","plain":"Mixed apnea index: mixed apneas per hour of sleep.","why":"Separates mixed events from obstructive and central events.","confusion":"Not the same as movement arousal index.","linked":["Scoring","Reports"]},{"term":"ODI","category":"Respiratory Metrics","plain":"Oxygen desaturation index: qualifying desaturations per hour of sleep or monitoring time, depending on study/report convention.","why":"Summarizes recurrent oxygen drops.","confusion":"ODI is not identical to AHI.","linked":["Oximetry","Reports"]},{"term":"TST","category":"Sleep Time","plain":"Total sleep time: total minutes scored as sleep.","why":"Used as the denominator for many PSG indexes.","confusion":"TST is not time in bed or total recording time.","linked":["Staging","Reports"]},{"term":"TRT","category":"Sleep Time","plain":"Total recording time: the recorded interval used by the report, often lights-out to lights-on when those define the study interval.","why":"Used in sleep efficiency and reporting context.","confusion":"TRT includes wake and sleep.","linked":["Reports"]},{"term":"TIB","category":"Sleep Time","plain":"Time in bed: the interval the patient is considered in bed for the study/reporting convention.","why":"May be used as the sleep-efficiency denominator in some reporting conventions.","confusion":"Do not assume TIB and TRT are always identical.","linked":["Reports"]},{"term":"WASO","category":"Sleep Time","plain":"Wake after sleep onset: wake time after initial sleep onset.","why":"Reflects sleep-maintenance disruption.","confusion":"WASO is not sleep-onset latency.","linked":["Reports"]},{"term":"SOL","category":"Sleep Time","plain":"Sleep onset latency: time from the defined study start/lights out to sleep onset.","why":"Measures how long it took to fall asleep.","confusion":"Start point depends on reporting convention; read the question carefully.","linked":["Reports"]},{"term":"REM latency","category":"Sleep Time","plain":"Time from sleep onset to the first epoch of REM sleep.","why":"Useful in interpretation of sleep architecture and hypersomnolence testing context.","confusion":"REM latency starts at sleep onset, not lights out.","linked":["Staging","Reports"]},{"term":"Sleep efficiency","category":"Sleep Time","plain":"Percentage of the defined recording/time-in-bed interval spent asleep.","why":"Summarizes sleep continuity.","confusion":"Use the denominator specified by the report or question.","linked":["Reports","Math Coach"]},{"term":"PLMI","category":"Movement","plain":"Periodic limb movement index: periodic limb movements per hour of sleep.","why":"Quantifies limb-movement frequency.","confusion":"PLMI does not by itself diagnose PLMD.","linked":["Movement","Reports"]},{"term":"Arousal index","category":"Arousal","plain":"Number of scored arousals per hour of sleep.","why":"Summarizes sleep fragmentation.","confusion":"Do not use total recording time in the denominator for PSG arousal index.","linked":["Arousal","Reports"]},{"term":"SpO2","category":"Oxygenation","plain":"Peripheral oxygen saturation estimated by pulse oximetry.","why":"Core overnight oxygenation signal.","confusion":"SpO2 does not directly measure ventilation or CO2.","linked":["Oximetry","Respiratory"]},{"term":"SaO2","category":"Oxygenation","plain":"Arterial oxygen saturation measured in arterial blood/co-oximetry context.","why":"Represents blood oxygen saturation by a different method than pulse oximetry.","confusion":"SaO2 is not PaO2.","linked":["Oximetry"]},{"term":"PaO2","category":"Blood Gas","plain":"Arterial partial pressure of oxygen, measured in mmHg.","why":"Direct arterial oxygen-pressure measure.","confusion":"PaO2 is pressure, not percent saturation.","linked":["Blood Gas"]},{"term":"PaCO2","category":"Blood Gas","plain":"Arterial partial pressure of carbon dioxide, measured in mmHg.","why":"Key measure of ventilation.","confusion":"Normal SpO2 does not guarantee normal PaCO2.","linked":["CO2","Blood Gas"]},{"term":"EtCO2","category":"CO2","plain":"End-tidal carbon dioxide measured at the end of exhalation by capnography.","why":"Provides breath-by-breath CO2 trend information.","confusion":"Leaks and mouth breathing can affect sampling.","linked":["CO2","Pediatrics"]},{"term":"TcCO2","category":"CO2","plain":"Transcutaneous carbon dioxide estimated through a heated skin sensor.","why":"Provides a slower trend of CO2 across sleep.","confusion":"TcCO2 lags faster changes compared with end-tidal sampling.","linked":["CO2","Pediatrics"]},{"term":"FiO2","category":"Oxygen Therapy","plain":"Fraction of inspired oxygen delivered to the patient.","why":"Describes the oxygen concentration going in.","confusion":"FiO2 is not the patient's SpO2.","linked":["Oxygen","Therapy"]},{"term":"CPAP","category":"PAP","plain":"Continuous positive airway pressure: one continuous positive pressure through the respiratory cycle.","why":"Common therapy for obstructive sleep apnea.","confusion":"CPAP has one pressure level, unlike bilevel PAP.","linked":["PAP"]},{"term":"BPAP","category":"PAP","plain":"Bilevel positive airway pressure with separate inspiratory and expiratory pressure settings.","why":"Allows IPAP and EPAP to differ.","confusion":"BPAP is not simply 'high CPAP'.","linked":["PAP"]},{"term":"IPAP","category":"PAP","plain":"Inspiratory positive airway pressure.","why":"The higher pressure in a typical bilevel setup.","confusion":"IPAP is not oxygen flow.","linked":["PAP"]},{"term":"EPAP","category":"PAP","plain":"Expiratory positive airway pressure.","why":"Supports airway patency during exhalation in bilevel therapy.","confusion":"EPAP is not EtCO2.","linked":["PAP"]},{"term":"Pressure support","category":"PAP","plain":"The difference between IPAP and EPAP.","why":"Represents inspiratory assistance above EPAP.","confusion":"Pressure support is measured in cm H2O, not L/min.","linked":["PAP","Math Coach"]},{"term":"ASV","category":"PAP","plain":"Adaptive servo-ventilation: PAP mode that varies pressure support in response to breathing pattern.","why":"Used in selected central-breathing treatment contexts.","confusion":"Appropriateness depends on clinical context and current guidance.","linked":["PAP"]},{"term":"AVAPS","category":"PAP","plain":"Average volume-assured pressure support: adjusts pressure support toward a ventilation target.","why":"Connects bilevel support with a ventilation target.","confusion":"Do not confuse pressure support with oxygen flow.","linked":["PAP"]},{"term":"RIP","category":"Respiratory Sensors","plain":"Respiratory inductance plethysmography used to estimate thoracic and abdominal respiratory effort.","why":"Core PSG effort signal.","confusion":"RIP measures effort, not airflow.","linked":["Sensors","Respiratory"]},{"term":"Thermistor","category":"Respiratory Sensors","plain":"Thermal airflow sensor that detects temperature changes between inhaled and exhaled air.","why":"Used for airflow detection, especially apnea detection context.","confusion":"Nasal pressure is more sensitive to flow limitation.","linked":["Sensors","Respiratory"]},{"term":"Nasal pressure","category":"Respiratory Sensors","plain":"Pressure-based airflow signal from a nasal cannula/transducer.","why":"Sensitive to reduced airflow and inspiratory flattening.","confusion":"Mouth breathing may reduce the nasal-pressure signal.","linked":["Sensors","Respiratory"]},{"term":"Snore sensor","category":"Respiratory Sensors","plain":"Sensor or microphone used to detect snoring vibration/sound.","why":"Supports respiratory pattern interpretation.","confusion":"Snore alone does not define an apnea or hypopnea.","linked":["Sensors"]},{"term":"EEG","category":"Neurophysiology","plain":"Electroencephalogram: scalp-recorded electrical activity used for sleep staging and arousal recognition.","why":"Core sleep-stage signal.","confusion":"EEG amplitude and frequency are different properties.","linked":["Staging","Signals"]},{"term":"EOG","category":"Neurophysiology","plain":"Electrooculogram: records eye movements through the corneo-retinal potential.","why":"Helps identify slow eye movements and rapid eye movements.","confusion":"EOG is not EMG.","linked":["Staging","Signals"]},{"term":"EMG","category":"Neurophysiology","plain":"Electromyogram: records muscle electrical activity.","why":"Chin EMG helps staging; limb EMG supports movement scoring.","confusion":"Muscle artifact can contaminate EEG channels.","linked":["Staging","Movement"]},{"term":"ECG","category":"Cardiac","plain":"Electrocardiogram: records cardiac electrical activity.","why":"Monitors heart rhythm during PSG.","confusion":"A clean tracing is needed before rhythm conclusions.","linked":["Cardiac","Signals"]},{"term":"N1","category":"Sleep Staging","plain":"Light NREM sleep characterized by low-amplitude mixed-frequency EEG and other stage-specific features.","why":"Marks transition from wake into sleep.","confusion":"Do not confuse slow eye movements alone with a complete stage decision.","linked":["Staging"]},{"term":"N2","category":"Sleep Staging","plain":"NREM stage identified by sleep spindles and/or K-complexes when criteria are met.","why":"Typically makes up a large portion of adult sleep.","confusion":"Arousal and transition rules can end N2 under defined conditions.","linked":["Staging"]},{"term":"N3","category":"Sleep Staging","plain":"NREM slow-wave sleep defined by sufficient delta activity meeting amplitude/duration criteria.","why":"Represents deep NREM sleep.","confusion":"Do not count artifact as slow-wave activity.","linked":["Staging"]},{"term":"REM","category":"Sleep Staging","plain":"Stage with rapid eye movements, low chin tone, and characteristic EEG pattern when criteria are met.","why":"Important for architecture, respiratory pattern, and parasomnia interpretation.","confusion":"Eye movements alone do not establish REM without the full criteria.","linked":["Staging"]},{"term":"K-complex","category":"Sleep Staging","plain":"Distinct high-amplitude biphasic EEG waveform used as an N2 marker when criteria are met.","why":"One of the key N2 features.","confusion":"A K-complex can be spontaneous or associated with stimuli/arousal context.","linked":["Staging"]},{"term":"Sleep spindle","category":"Sleep Staging","plain":"Burst of sigma-frequency EEG activity used as an N2 marker when criteria are met.","why":"Classic N2 feature.","confusion":"Do not confuse muscle artifact with spindle activity.","linked":["Staging"]},{"term":"Sawtooth waves","category":"Sleep Staging","plain":"Triangular, serrated EEG waves often associated with REM sleep.","why":"Can support REM recognition.","confusion":"They are supportive features, not the only REM criterion.","linked":["Staging"]},{"term":"Slow eye movements","category":"Sleep Staging","plain":"Rolling eye movements commonly seen during drowsiness/N1 transition.","why":"Supports wake-to-N1 transition recognition.","confusion":"Slow eye movements can occur before formal sleep onset.","linked":["Staging"]},{"term":"Alpha rhythm","category":"Sleep Staging","plain":"Posterior dominant rhythm commonly around 8-13 Hz in relaxed wakefulness with eyes closed.","why":"Useful in determining wake and sleep onset.","confusion":"Alpha intrusion can occur in sleep and is not always wake.","linked":["Staging"]},{"term":"Delta activity","category":"Sleep Staging","plain":"Slow EEG activity used in determining N3 when amplitude/duration criteria are met.","why":"Core feature of deep sleep staging.","confusion":"Very slow artifact is not automatically delta sleep.","linked":["Staging"]},{"term":"Arousal","category":"Arousal","plain":"Abrupt EEG frequency shift meeting duration and prior-sleep requirements, with additional chin EMG criteria in REM when applicable.","why":"Core sleep-fragmentation event.","confusion":"A brief 1-2 second change does not meet standard arousal duration.","linked":["Scoring","Arousal"]},{"term":"Obstructive apnea","category":"Respiratory Events","plain":"Marked/complete airflow reduction with continued or increased respiratory effort.","why":"Key obstructive respiratory event.","confusion":"Effort channels separate obstructive from central apnea.","linked":["Scoring","Respiratory"]},{"term":"Central apnea","category":"Respiratory Events","plain":"Marked/complete airflow reduction accompanied by absent respiratory effort.","why":"Key central respiratory event.","confusion":"Airflow loss alone cannot classify the event as central.","linked":["Scoring","Respiratory"]},{"term":"Mixed apnea","category":"Respiratory Events","plain":"Apnea with a central portion followed by obstructive respiratory effort.","why":"Contains both absent-effort and obstructive components.","confusion":"Do not label based on only the beginning or end of the event.","linked":["Scoring","Respiratory"]},{"term":"Hypopnea","category":"Respiratory Events","plain":"Partial airflow reduction meeting current duration and consequence criteria.","why":"Major component of AHI.","confusion":"Flow limitation alone may not meet hypopnea criteria.","linked":["Scoring","Respiratory"]},{"term":"Flow limitation","category":"Respiratory Events","plain":"Flattening or reduced inspiratory flow suggesting upper-airway resistance without necessarily meeting apnea/hypopnea criteria.","why":"Helps identify subtle obstructive breathing.","confusion":"Not every flattened breath is a scored respiratory event.","linked":["Respiratory"]},{"term":"Cheyne-Stokes breathing","category":"Respiratory Patterns","plain":"Cyclic crescendo-decrescendo breathing pattern associated with central events in appropriate clinical context.","why":"Important central-breathing pattern.","confusion":"Do not confuse any waxing-waning pattern with formal Cheyne-Stokes criteria.","linked":["Respiratory","Cardiac"]},{"term":"Periodic breathing","category":"Respiratory Patterns","plain":"Repeated waxing-and-waning breathing pattern that may occur in several contexts.","why":"Broader pattern than Cheyne-Stokes respiration.","confusion":"Cheyne-Stokes has additional pattern/context expectations.","linked":["Respiratory"]},{"term":"Hypoventilation","category":"Respiratory Patterns","plain":"Inadequate ventilation resulting in elevated CO2 during sleep or wake, interpreted with appropriate criteria/context.","why":"CO2 monitoring is central to recognition.","confusion":"Low SpO2 alone does not prove hypoventilation.","linked":["CO2","Respiratory"]},{"term":"Parasomnia","category":"Sleep Disorders","plain":"Undesired behavior or experience occurring during entry into sleep, sleep, or arousal from sleep.","why":"History, timing, stage, and video can help differentiate disorders.","confusion":"Not all nocturnal behaviors are parasomnias.","linked":["Sleep Disorders"]},{"term":"RBD","category":"Sleep Disorders","plain":"REM sleep behavior disorder: dream enactment associated with loss of normal REM atonia when confirmed in the correct context.","why":"PSG chin/limb EMG and video are important.","confusion":"OSA, medications, and other mimics can resemble dream enactment.","linked":["Sleep Disorders","REM"]},{"term":"RLS","category":"Sleep Disorders","plain":"Restless legs syndrome: urge to move the legs, worse at rest, relieved by movement, and worse in evening/night.","why":"Clinical history diagnosis.","confusion":"RLS is not the same as PLMS on PSG.","linked":["Sleep Disorders","Movement"]},{"term":"PLMS","category":"Movement","plain":"Periodic limb movements during sleep scored from limb EMG when pattern criteria are met.","why":"May fragment sleep or occur with other disorders.","confusion":"PLMS alone does not equal PLMD.","linked":["Movement","Scoring"]},{"term":"MSLT","category":"Hypersomnolence Testing","plain":"Multiple Sleep Latency Test: daytime nap protocol used to assess physiologic sleepiness and SOREMPs under standardized conditions.","why":"Supports evaluation of narcolepsy and hypersomnolence.","confusion":"Protocol quality, prior sleep, medications, and timing matter.","linked":["MSLT","Hypersomnolence"]},{"term":"MWT","category":"Hypersomnolence Testing","plain":"Maintenance of Wakefulness Test: assesses ability to remain awake under standardized conditions.","why":"Used in selected clinical/occupational contexts.","confusion":"MWT asks the patient to stay awake; MSLT asks the patient to try to sleep.","linked":["MWT"]},{"term":"SOREMP","category":"Hypersomnolence Testing","plain":"Sleep-onset REM period: REM sleep occurring near sleep onset under defined criteria.","why":"Important in narcolepsy testing.","confusion":"A SOREMP must be interpreted with the full protocol and prior sleep/medication context.","linked":["MSLT","REM"]},{"term":"HSAT","category":"Testing","plain":"Home sleep apnea test: limited-channel unattended testing for selected patients, primarily for obstructive sleep apnea evaluation.","why":"Different signals and denominator than attended PSG.","confusion":"HSAT does not directly measure sleep stages in most setups.","linked":["HSAT"]},{"term":"PSG","category":"Testing","plain":"Polysomnography: multichannel sleep study recording physiologic signals used to evaluate sleep and sleep disorders.","why":"Core test in sleep technology.","confusion":"PSG is broader than an oximetry or airflow-only study.","linked":["Testing"]},{"term":"PAP titration","category":"Testing","plain":"Study or study portion in which PAP settings are adjusted according to protocol to control sleep-disordered breathing and optimize therapy.","why":"Connects event recognition with treatment response.","confusion":"Technologist titration follows protocol/order; it is not independent prescribing.","linked":["PAP","Testing"]},{"term":"Split-night study","category":"Testing","plain":"Study that begins diagnostically and transitions to PAP titration after criteria/protocol requirements are met.","why":"Combines diagnostic and treatment components in one night.","confusion":"Do not switch to titration simply because events are present; follow criteria/protocol.","linked":["Testing","PAP"]},{"term":"Lights out","category":"Study Timing","plain":"Documented time the study's sleep opportunity/recording interval is initiated according to protocol.","why":"Used in report timing and latency context.","confusion":"Lights out may not equal sleep onset.","linked":["Reports"]},{"term":"Lights on","category":"Study Timing","plain":"Documented time the overnight sleep opportunity/recording interval ends according to protocol.","why":"Used in recording-time calculations.","confusion":"Lights on is not necessarily final awakening time.","linked":["Reports"]},{"term":"Biocalibration","category":"Technical","plain":"Patient maneuvers performed to confirm physiologic channel response before/after the recording.","why":"Helps verify channel identity and function.","confusion":"Biocalibration is different from electronic calibration.","linked":["Technical","Signals"]},{"term":"Impedance","category":"Technical","plain":"Opposition to alternating electrical current at the electrode-skin interface, measured in ohms.","why":"Important for signal quality.","confusion":"High or unequal impedance can increase noise; do not confuse impedance with signal amplitude.","linked":["Technical","Signals"]},{"term":"LFF","category":"Technical","plain":"Low-frequency filter: attenuates frequencies below the cutoff.","why":"Controls slow components shown in a channel.","confusion":"Raising LFF removes more slow activity.","linked":["Technical","Signals"]},{"term":"HFF","category":"Technical","plain":"High-frequency filter: attenuates frequencies above the cutoff.","why":"Controls fast components shown in a channel.","confusion":"Lowering HFF removes more fast activity.","linked":["Technical","Signals"]},{"term":"Notch filter","category":"Technical","plain":"Narrow filter targeting a specific interference frequency, often line noise.","why":"Can reduce line-frequency artifact.","confusion":"Fix signal/source problems before relying on the notch filter.","linked":["Technical","Signals"]},{"term":"Sampling rate","category":"Technical","plain":"Number of signal samples recorded each second.","why":"Determines how well the digital recording represents changing signals.","confusion":"Sampling rate is not display sensitivity.","linked":["Technical","Signals"]},{"term":"Aliasing","category":"Technical","plain":"False lower-frequency appearance caused by sampling a higher-frequency signal too slowly.","why":"Important digital-recording concept.","confusion":"Aliasing is not a physiologic rhythm.","linked":["Technical","Signals"]},{"term":"Ground loop","category":"Technical","plain":"Electrical noise caused by unintended multiple grounding paths or electrical-potential differences.","why":"Important equipment/safety troubleshooting concept.","confusion":"Never defeat safety grounding to eliminate artifact.","linked":["Technical","Safety"]},{"term":"Salt bridge","category":"Technical","plain":"Conductive material electrically connects nearby electrodes and reduces the true differential signal.","why":"Common setup problem.","confusion":"Changing sensitivity will not fix the bridge.","linked":["Technical","Signals"]},{"term":"Electrode pop","category":"Technical","plain":"Abrupt artifact caused by unstable electrode contact or electrode-skin interface changes.","why":"Can mimic sharp physiologic activity.","confusion":"Check electrode integrity first.","linked":["Technical","Signals"]},{"term":"60-Hz artifact","category":"Technical","plain":"Line-frequency electrical interference appearing as regular fast noise.","why":"Common PSG technical issue.","confusion":"Find the source before using a notch filter as the only fix.","linked":["Technical","Signals"]},{"term":"Common-mode rejection","category":"Technical","plain":"Differential amplifier ability to reject signals shared by both inputs.","why":"Helps reduce common electrical noise.","confusion":"Good rejection cannot correct every setup problem.","linked":["Technical","Signals"]},{"term":"Differential amplifier","category":"Technical","plain":"Amplifier that magnifies the difference between two input voltages while rejecting shared signals.","why":"Foundation of PSG electrophysiologic channels.","confusion":"If both inputs are identical, the differential signal is near zero.","linked":["Technical","Signals"]},{"term":"Leakage current","category":"Safety","plain":"Small unintended current that may flow through equipment pathways and is controlled by safety standards/testing.","why":"Part of electrical safety.","confusion":"Electrical safety problems require facility/biomedical procedures, not improvised fixes.","linked":["Safety","Technical"]},{"term":"Standard precautions","category":"Safety","plain":"Infection-prevention approach treating blood/body-fluid exposure risks consistently according to current policy and guidance.","why":"Core patient/staff safety practice.","confusion":"Precautions depend on exposure risk and current facility/CDC guidance.","linked":["Safety","Infection Control"]},{"term":"PPE","category":"Safety","plain":"Personal protective equipment selected based on expected exposure risk.","why":"Protects staff and patients during procedures.","confusion":"PPE selection should match the task and current policy.","linked":["Safety","Infection Control"]},{"term":"HIPAA","category":"Professional Practice","plain":"U.S. privacy framework protecting individually identifiable health information.","why":"Sleep technologists handle sensitive patient data.","confusion":"Do not include unnecessary patient identifiers in educational tools or personal study notes.","linked":["Professional Practice"]},{"term":"RACE","category":"Safety","plain":"Common fire-response mnemonic used in many facilities, with exact wording/order verified against local policy.","why":"Supports emergency preparedness.","confusion":"Facility policy is controlling.","linked":["Safety"]},{"term":"PASS","category":"Safety","plain":"Common fire-extinguisher mnemonic used in many facilities; verify local training/policy.","why":"Supports emergency response knowledge.","confusion":"Do not use a fire extinguisher when evacuation or another response is required by policy.","linked":["Safety"]},{"term":"10-20 system","category":"Electrode Placement","plain":"Standard proportional head-measurement system used to locate EEG electrodes.","why":"Foundation of PSG electrode placement.","confusion":"Do not eyeball locations; measure according to the system.","linked":["Electrodes","Technical"]},{"term":"M1","category":"Electrode Placement","plain":"Left mastoid/auricular reference location used in standard PSG derivations.","why":"Common reference site.","confusion":"M1 is left; M2 is right.","linked":["Electrodes"]},{"term":"M2","category":"Electrode Placement","plain":"Right mastoid/auricular reference location used in standard PSG derivations.","why":"Common reference site.","confusion":"M2 is right; M1 is left.","linked":["Electrodes"]},{"term":"F3/F4","category":"Electrode Placement","plain":"Left/right frontal EEG electrode positions in the international 10-20 system.","why":"Used in recommended PSG EEG derivations.","confusion":"Odd numbers are left, even numbers are right.","linked":["Electrodes","Staging"]},{"term":"C3/C4","category":"Electrode Placement","plain":"Left/right central EEG electrode positions.","why":"Classic PSG EEG derivation sites.","confusion":"Odd left, even right.","linked":["Electrodes","Staging"]},{"term":"O1/O2","category":"Electrode Placement","plain":"Left/right occipital EEG electrode positions.","why":"Useful for posterior alpha and sleep staging.","confusion":"Odd left, even right.","linked":["Electrodes","Staging"]},{"term":"Chin EMG","category":"Electrode Placement","plain":"Submental/chin muscle recording used for sleep staging and REM atonia assessment.","why":"Core PSG channel.","confusion":"Placement and signal quality affect staging interpretation.","linked":["Electrodes","Staging"]},{"term":"Anterior tibialis EMG","category":"Electrode Placement","plain":"Leg muscle recording used for limb-movement detection/scoring.","why":"Core movement channel.","confusion":"Artifact and voluntary movement must be distinguished from periodic limb movements.","linked":["Electrodes","Movement"]},{"term":"ECG Lead II","category":"Electrode Placement","plain":"Common ECG orientation used in PSG for rhythm monitoring.","why":"Provides useful P-QRS-T visualization.","confusion":"Exact PSG derivation/placement follows current standards and lab protocol.","linked":["Cardiac","Electrodes"]},{"term":"Snoring","category":"Respiratory","plain":"Upper-airway sound/vibration occurring during sleep.","why":"Can support obstructive-breathing assessment.","confusion":"Snoring alone does not diagnose OSA.","linked":["Respiratory"]},{"term":"Paradoxical breathing","category":"Respiratory","plain":"Thoracic and abdominal effort moving in opposite directions.","why":"Can support obstructive effort interpretation.","confusion":"Sensor artifact can mimic paradox; verify signal quality.","linked":["Respiratory"]},{"term":"Thoracoabdominal asynchrony","category":"Respiratory","plain":"Chest and abdominal respiratory movements are poorly synchronized.","why":"May occur with increased work of breathing/obstruction.","confusion":"Check RIP belt placement and signal integrity.","linked":["Respiratory"]},{"term":"PAP leak","category":"PAP","plain":"Air escaping unintentionally from PAP interface or mouth.","why":"Can reduce effective therapy and distort device signals.","confusion":"Fix leak before assuming inadequate pressure.","linked":["PAP"]},{"term":"Rainout","category":"PAP","plain":"Condensation accumulating in PAP tubing or interface.","why":"Common comfort/troubleshooting issue.","confusion":"Rainout is a humidity/temperature issue, not a respiratory event.","linked":["PAP"]},{"term":"Humidification","category":"PAP","plain":"Moisture added to PAP airflow to reduce dryness and improve comfort.","why":"Can improve tolerance.","confusion":"Excess humidity with cool tubing can contribute to rainout.","linked":["PAP"]},{"term":"Ramp","category":"PAP","plain":"Comfort feature starting PAP at lower pressure before gradually increasing.","why":"May improve sleep-onset comfort.","confusion":"Ramp pressure is not necessarily therapeutic pressure.","linked":["PAP"]},{"term":"Mask fit","category":"PAP","plain":"Appropriate interface size, position, seal, and comfort for the patient.","why":"Critical for treatment effectiveness and tolerance.","confusion":"Overtightening can worsen discomfort/leak.","linked":["PAP"]},{"term":"Oxygen bleed-in","category":"Oxygen Therapy","plain":"Supplemental oxygen introduced into a PAP circuit through an adapter/connector.","why":"Used in selected ordered/protocol-directed situations.","confusion":"Oxygen flow is documented separately from PAP pressure.","linked":["Oxygen","PAP"]},{"term":"L/min","category":"Units","plain":"Liters per minute, commonly used for oxygen flow.","why":"Core oxygen-therapy unit.","confusion":"Do not use L/min for PAP pressure.","linked":["Oxygen","Math Coach"]},{"term":"cm H2O","category":"Units","plain":"Centimeters of water, commonly used for PAP pressure.","why":"Core PAP unit.","confusion":"Do not use cm H2O for blood-gas pressure.","linked":["PAP","Math Coach"]},{"term":"mmHg","category":"Units","plain":"Millimeters of mercury, used for blood pressure and blood-gas/CO2 pressure measurements.","why":"Core blood-gas/pressure unit.","confusion":"Do not use mmHg for PAP pressure.","linked":["CO2","Blood Gas"]},{"term":"Hz","category":"Units","plain":"Hertz: cycles per second.","why":"Unit of frequency and sampling rate.","confusion":"Hz is not amplitude.","linked":["Signals","Math Coach"]},{"term":"µV","category":"Units","plain":"Microvolts, commonly used for small electrophysiologic signal amplitudes.","why":"Core EEG/EOG/EMG amplitude unit.","confusion":"µV is amplitude, not frequency.","linked":["Signals"]},{"term":"kΩ","category":"Units","plain":"Kilo-ohms, commonly used for electrode impedance checks.","why":"Core setup-quality unit.","confusion":"kΩ is resistance/impedance, not voltage.","linked":["Technical"]},{"term":"BPM","category":"Units","plain":"Beats per minute, unit of heart rate.","why":"Core cardiac-rate unit.","confusion":"Do not confuse heart rate with respiratory rate.","linked":["Cardiac"]},{"term":"RR","category":"Units","plain":"Respiratory rate, usually breaths per minute in context.","why":"Summarizes breathing frequency.","confusion":"RR may also be used for R-R interval in ECG context; read the context.","linked":["Respiratory","Cardiac"]}],"mathLessons":[{"id":"epoch-time","short":"Epochs","title":"Epoch Time Basics","tag":"30-sec epochs","unit":"seconds/minutes","formula":"1 epoch = 30 seconds; 2 epochs = 1 minute","concept":"Most PSG scoring time math starts with the 30-second epoch. Two epochs equal one minute. When a question gives epoch counts, convert carefully before using the number in another formula.","trap":"Do not divide by 30 when the question already converted to minutes. Do not treat an epoch as one minute.","example":["A study shows 10 epochs of wake after sleep onset.","Each epoch is 30 seconds.","10 x 30 = 300 seconds.","300 / 60 = 5 minutes."],"solve":["Find seconds: epochs x 30","Find minutes: epochs / 2","Find epochs: minutes x 2"],"questions":[{"q":"How many minutes are in 24 standard PSG epochs?","choices":["6 minutes","12 minutes","24 minutes","48 minutes"],"a":"12 minutes","why":"Two 30-second epochs equal 1 minute. 24 / 2 = 12 minutes."},{"q":"A patient has 18 epochs of wake after sleep onset. How many minutes is that?","choices":["9 minutes","18 minutes","30 minutes","36 minutes"],"a":"9 minutes","why":"18 epochs / 2 = 9 minutes."},{"q":"A tech says 20 epochs equals 20 minutes. What is the problem?","choices":["Each standard epoch is 30 seconds, so 20 epochs equals 10 minutes","Epochs are measured in kΩ","Epochs are PAP pressures","Each epoch is one hour"],"a":"Each standard epoch is 30 seconds, so 20 epochs equals 10 minutes","why":"Two epochs equal one minute."},{"q":"How many epochs are in 7.5 minutes?","choices":["7.5","10","15","30"],"a":"15","why":"Minutes x 2 = epochs. 7.5 x 2 = 15 epochs."},{"q":"Which unit belongs to epoch duration?","choices":["seconds","kΩ","cm H2O","L/min"],"a":"seconds","why":"An epoch is a time segment, usually 30 seconds."}]},{"id":"trt","short":"TRT","title":"Total Recording Time","tag":"clock math","unit":"minutes","formula":"TRT = lights on - lights out","concept":"Total recording time is the time from lights out to lights on when those times define the recorded study interval.","trap":"Watch for crossing midnight. Convert both clock times to minutes on a 24-hour clock if needed.","example":["Lights out: 22:30","Lights on: 06:30 next morning","From 22:30 to midnight = 90 minutes","Midnight to 06:30 = 390 minutes","TRT = 480 minutes"],"solve":["Convert clock times to minutes if needed","If the study crosses midnight, split at midnight or add 24 hours","Subtract start from end"],"questions":[{"q":"Lights out is 23:00 and lights on is 07:00. What is TRT?","choices":["420 minutes","480 minutes","540 minutes","600 minutes"],"a":"480 minutes","why":"23:00 to 07:00 is 8 hours = 480 minutes."},{"q":"Lights out is 22:15 and lights on is 06:15. What is TRT?","choices":["420 minutes","450 minutes","480 minutes","510 minutes"],"a":"480 minutes","why":"The interval is exactly 8 hours."},{"q":"Lights out is 21:45 and lights on is 05:45. What is TRT?","choices":["420 minutes","450 minutes","480 minutes","540 minutes"],"a":"480 minutes","why":"21:45 to 05:45 is 8 hours."},{"q":"Which times are used to calculate TRT in this lesson?","choices":["Sleep onset and REM onset","Lights out and lights on","First apnea and last apnea","First arousal and final awakening"],"a":"Lights out and lights on","why":"TRT uses the defined recording interval."},{"q":"Why is midnight a common clock-math trap?","choices":["The end time may be numerically smaller than the start time","Midnight changes the EEG voltage","The PAP pressure resets","TST always becomes zero"],"a":"The end time may be numerically smaller than the start time","why":"Use a 24-hour timeline or split the interval at midnight."}]},{"id":"sol","short":"SOL","title":"Sleep Onset Latency","tag":"latency","unit":"minutes","formula":"SOL = sleep onset - lights out","concept":"Sleep onset latency measures how long it takes the patient to reach the defined first epoch of sleep after lights out.","trap":"Do not start REM latency from lights out. Sleep onset latency and REM latency use different start points.","example":["Lights out: 22:30","Sleep onset: 22:48","SOL = 18 minutes"],"solve":["Identify lights out","Identify the defined sleep onset","Subtract lights out from sleep onset"],"questions":[{"q":"Lights out is 22:00 and sleep onset is 22:27. What is SOL?","choices":["17 minutes","27 minutes","37 minutes","60 minutes"],"a":"27 minutes","why":"22:27 - 22:00 = 27 minutes."},{"q":"Lights out is 21:45 and sleep onset is 22:05. What is SOL?","choices":["10 minutes","20 minutes","35 minutes","45 minutes"],"a":"20 minutes","why":"21:45 to 22:05 is 20 minutes."},{"q":"What is the starting point for SOL in this lesson?","choices":["REM onset","Lights out","Final awakening","First apnea"],"a":"Lights out","why":"SOL is measured from lights out to sleep onset."},{"q":"A patient falls asleep 12 minutes after lights out. What is SOL?","choices":["6 minutes","12 minutes","24 minutes","30 minutes"],"a":"12 minutes","why":"SOL is the elapsed time to sleep onset."},{"q":"Which is the most direct unit for SOL?","choices":["minutes","cm H2O","L/min","kΩ"],"a":"minutes","why":"Latency is a time measure."}]},{"id":"rem-latency","short":"REM Latency","title":"REM Latency","tag":"latency","unit":"minutes","formula":"REM latency = first REM onset - sleep onset","concept":"REM latency measures the time from sleep onset to the first epoch of REM sleep.","trap":"Do not calculate REM latency from lights out unless the question specifically defines another convention.","example":["Sleep onset: 22:40","First REM: 00:10","REM latency = 90 minutes"],"solve":["Identify sleep onset","Identify first REM onset","Subtract, crossing midnight carefully if needed"],"questions":[{"q":"Sleep onset is 22:30 and first REM begins at 00:00. What is REM latency?","choices":["60 minutes","90 minutes","120 minutes","150 minutes"],"a":"90 minutes","why":"22:30 to midnight is 90 minutes."},{"q":"Sleep onset is 23:00 and first REM begins at 00:20. What is REM latency?","choices":["20 minutes","60 minutes","80 minutes","100 minutes"],"a":"80 minutes","why":"23:00 to 00:20 is 80 minutes."},{"q":"What is the starting point for REM latency?","choices":["Lights out","Sleep onset","First arousal","Lights on"],"a":"Sleep onset","why":"REM latency begins at sleep onset."},{"q":"Why can crossing midnight confuse REM latency calculations?","choices":["Clock times wrap to a smaller number","REM stops at midnight","EEG frequency resets","The patient must wake"],"a":"Clock times wrap to a smaller number","why":"Use an elapsed-time approach."},{"q":"REM latency is best described as what type of measurement?","choices":["time interval","pressure","flow","impedance"],"a":"time interval","why":"REM latency is elapsed time."}]},{"id":"tst-waso","short":"TST / WASO","title":"Total Sleep Time and WASO","tag":"sleep time","unit":"minutes","formula":"TST = sum of sleep-stage minutes; WASO = wake after sleep onset","concept":"Total sleep time is the amount of actual sleep. WASO is wake time that occurs after sleep onset.","trap":"Do not include wake in TST. Do not include sleep-onset latency in WASO unless the question defines it that way.","example":["N1 = 20 min, N2 = 240 min, N3 = 60 min, REM = 80 min","TST = 400 min","If 35 min of wake occurs after sleep onset, WASO = 35 min"],"solve":["Add N1 + N2 + N3 + REM for TST","Count wake after sleep onset for WASO","Keep the two measures separate"],"questions":[{"q":"N1 20 min, N2 220 min, N3 70 min, REM 90 min. What is TST?","choices":["310 minutes","350 minutes","400 minutes","420 minutes"],"a":"400 minutes","why":"20 + 220 + 70 + 90 = 400 minutes."},{"q":"A patient has 42 minutes of wake after first falling asleep. What is WASO?","choices":["21 minutes","42 minutes","84 minutes","Cannot be measured"],"a":"42 minutes","why":"WASO is wake after sleep onset."},{"q":"Which time is excluded from TST?","choices":["N2","REM","Wake","N3"],"a":"Wake","why":"TST includes sleep stages, not wake."},{"q":"Why should SOL and WASO not be combined automatically?","choices":["They describe different parts of the night","Both are PAP pressures","WASO is in kΩ","SOL is oxygen flow"],"a":"They describe different parts of the night","why":"SOL is before sleep onset; WASO is after sleep onset."},{"q":"Which set adds up to TST?","choices":["N1 + N2 + N3 + REM","Wake + lights out + lights on","AHI + RDI + REI","IPAP + EPAP + oxygen"],"a":"N1 + N2 + N3 + REM","why":"TST is the sum of sleep-stage time."}]},{"id":"sleep-efficiency","short":"Efficiency","title":"Sleep Efficiency","tag":"percentage","unit":"%","formula":"Sleep efficiency = TST / TRT x 100","concept":"Sleep efficiency is the percentage of the recording interval spent asleep in this lesson's reporting convention.","trap":"Use the denominator given by the question. A common mistake is putting TST on the bottom or forgetting x 100.","example":["TST = 360 minutes","TRT = 480 minutes","360 / 480 = 0.75","0.75 x 100 = 75%"],"solve":["Put TST on top","Put TRT on bottom","Divide","Multiply by 100"],"questions":[{"q":"TST is 360 min and TRT is 480 min. What is sleep efficiency?","choices":["60%","75%","80%","133%"],"a":"75%","why":"360 / 480 x 100 = 75%."},{"q":"TST is 420 min and TRT is 480 min. What is sleep efficiency?","choices":["72.5%","80%","87.5%","114%"],"a":"87.5%","why":"420 / 480 x 100 = 87.5%."},{"q":"Which number belongs in the numerator?","choices":["TST","TRT","AHI","IPAP"],"a":"TST","why":"Sleep efficiency is TST divided by TRT in this lesson."},{"q":"A calculated sleep efficiency is 125%. What should you suspect first?","choices":["A setup or denominator error","Perfect sleep","High oxygen flow","Low impedance"],"a":"A setup or denominator error","why":"TST should not exceed the recording interval in a normal calculation."},{"q":"Why multiply by 100?","choices":["To convert the decimal ratio to percent","To convert minutes to hours","To calculate PAP pressure","To calculate impedance"],"a":"To convert the decimal ratio to percent","why":"A ratio of 0.75 becomes 75%."}]},{"id":"stage-percent","short":"Stage %","title":"Sleep Stage Percentages","tag":"percentage","unit":"%","formula":"Stage % = stage minutes / TST x 100","concept":"Sleep-stage percentages describe how much of total sleep time occurred in each stage.","trap":"Do not divide stage minutes by TRT. Sleep architecture percentages use total sleep time.","example":["REM = 80 minutes","TST = 400 minutes","80 / 400 x 100 = 20% REM"],"solve":["Find minutes in the stage","Divide by TST","Multiply by 100"],"questions":[{"q":"N3 is 60 min and TST is 400 min. What is N3 percentage?","choices":["10%","15%","20%","25%"],"a":"15%","why":"60 / 400 x 100 = 15%."},{"q":"REM is 90 min and TST is 450 min. What is REM percentage?","choices":["15%","20%","25%","30%"],"a":"20%","why":"90 / 450 x 100 = 20%."},{"q":"Which denominator belongs in sleep-stage percentage?","choices":["TST","TRT","Number of apneas","IPAP"],"a":"TST","why":"Stage percentages are proportions of actual sleep time."},{"q":"If N2 is 240 min and TST is 400 min, what is N2 percentage?","choices":["40%","50%","60%","80%"],"a":"60%","why":"240 / 400 x 100 = 60%."},{"q":"The sum of all sleep-stage percentages should be approximately what?","choices":["50%","75%","100%","200%"],"a":"100%","why":"All sleep stages together make up total sleep time."}]},{"id":"ahi","short":"AHI","title":"Apnea-Hypopnea Index","tag":"respiratory index","unit":"events/hour","formula":"AHI = (apneas + hypopneas) / TST hours","concept":"AHI is the number of apneas plus hypopneas per hour of total sleep time in a PSG.","trap":"Convert TST from minutes to hours. Do not use recording time when the question asks for PSG AHI.","example":["Apneas = 12","Hypopneas = 48","TST = 300 min = 5 hr","AHI = 60 / 5 = 12 events/hr"],"solve":["Add apneas + hypopneas","Convert TST minutes to hours","Divide events by sleep hours"],"questions":[{"q":"10 apneas + 40 hypopneas over 300 min TST. AHI?","choices":["5/hr","10/hr","12/hr","20/hr"],"a":"10/hr","why":"50 events / 5 hours = 10/hr."},{"q":"20 apneas + 40 hypopneas over 360 min TST. AHI?","choices":["6/hr","10/hr","12/hr","16/hr"],"a":"10/hr","why":"60 events / 6 hours = 10/hr."},{"q":"Why divide TST minutes by 60 before calculating AHI?","choices":["AHI is events per hour","AHI is a percentage","AHI is in cm H2O","AHI is a voltage"],"a":"AHI is events per hour","why":"The denominator must be hours."},{"q":"Which events belong in the basic AHI numerator?","choices":["Apneas + hypopneas","Arousals only","PLMs only","RERAs only"],"a":"Apneas + hypopneas","why":"Basic AHI counts apneas and hypopneas."},{"q":"A tech divides 80 events by 400 minutes and reports 0.2/hr. What is wrong?","choices":["TST was not converted to hours","Too many events were counted","AHI uses PAP pressure","The numerator should be oxygen flow"],"a":"TST was not converted to hours","why":"400 minutes = 6.67 hours, not 400 hours."}]},{"id":"rdi","short":"RDI","title":"Respiratory Disturbance Index","tag":"respiratory index","unit":"events/hour","formula":"RDI = (apneas + hypopneas + RERAs) / TST hours","concept":"RDI can include respiratory effort-related arousals in addition to apneas and hypopneas, depending on the reporting definition used.","trap":"If a question includes RERAs, do not automatically calculate AHI. Read the requested index.","example":["Apneas 10 + hypopneas 30 + RERAs 20 = 60 disturbances","TST = 300 min = 5 hr","RDI = 60 / 5 = 12/hr"],"solve":["Add all events included in the requested RDI definition","Convert TST to hours","Divide"],"questions":[{"q":"5 apneas + 25 hypopneas + 20 RERAs over 300 min TST. RDI?","choices":["6/hr","10/hr","12/hr","20/hr"],"a":"10/hr","why":"50 events / 5 hours = 10/hr."},{"q":"AHI is 8/hr and RDI is 14/hr. What most likely explains the difference?","choices":["RDI includes additional disturbances such as RERAs","AHI uses cm H2O","RDI ignores apneas","AHI is a percentage"],"a":"RDI includes additional disturbances such as RERAs","why":"RDI may include RERAs that AHI does not."},{"q":"Which denominator is used for PSG RDI in this lesson?","choices":["TST hours","TRT minutes","IPAP","oxygen flow"],"a":"TST hours","why":"RDI is expressed as events per hour of sleep."},{"q":"10 apneas + 10 hypopneas + 10 RERAs over 6 hours TST. RDI?","choices":["3/hr","5/hr","10/hr","30/hr"],"a":"5/hr","why":"30 / 6 = 5/hr."},{"q":"Which index specifically asks you to include RERAs in this lesson?","choices":["RDI","AHI","PLMI","ODI"],"a":"RDI","why":"RDI may include RERAs."}]},{"id":"rei","short":"REI","title":"Respiratory Event Index","tag":"HSAT index","unit":"events/hour","formula":"REI = respiratory events / monitoring time hours","concept":"REI is commonly used with home sleep apnea testing because true EEG-based total sleep time may not be available.","trap":"Do not assume REI denominator is TST. Use the monitoring/recording time defined by the question.","example":["Respiratory events = 80","Monitoring time = 8 hr","REI = 80 / 8 = 10/hr"],"solve":["Count qualifying respiratory events","Convert monitoring time to hours if needed","Divide events by monitoring hours"],"questions":[{"q":"60 respiratory events over 6 hours monitoring time. REI?","choices":["6/hr","10/hr","12/hr","60/hr"],"a":"10/hr","why":"60 / 6 = 10/hr."},{"q":"What is the usual denominator concept for REI in HSAT-style questions?","choices":["Monitoring/recording time","TST from EEG","IPAP","SpO2"],"a":"Monitoring/recording time","why":"HSAT often lacks EEG-based TST."},{"q":"If the patient is awake for part of an HSAT, what may happen to REI compared with a true sleep-time index?","choices":["It may underestimate event frequency during actual sleep","It always doubles","It becomes a pressure","It becomes a percentage"],"a":"It may underestimate event frequency during actual sleep","why":"Monitoring time may be longer than actual sleep time."},{"q":"90 events over 9 hours monitoring time. REI?","choices":["5/hr","10/hr","15/hr","90/hr"],"a":"10/hr","why":"90 / 9 = 10/hr."},{"q":"Which index is most associated with HSAT-style monitoring time?","choices":["REI","AHI","PLMI","Arousal index"],"a":"REI","why":"REI commonly uses monitoring time in HSAT."}]},{"id":"plmi","short":"PLMI","title":"Periodic Limb Movement Index","tag":"movement index","unit":"movements/hour","formula":"PLMI = periodic limb movements / TST hours","concept":"PLMI expresses the number of qualifying periodic limb movements per hour of sleep.","trap":"Use only movements that meet the scoring definition, and convert TST to hours.","example":["PLMs = 90","TST = 360 min = 6 hr","PLMI = 90 / 6 = 15/hr"],"solve":["Count qualifying PLMs","Convert TST to hours","Divide"],"questions":[{"q":"72 PLMs over 360 min TST. PLMI?","choices":["6/hr","10/hr","12/hr","20/hr"],"a":"12/hr","why":"72 / 6 = 12/hr."},{"q":"100 PLMs over 400 min TST. PLMI?","choices":["10/hr","12/hr","15/hr","25/hr"],"a":"15/hr","why":"400 min = 6.67 hr. 100 / 6.67 ≈ 15/hr."},{"q":"What denominator is used for PLMI?","choices":["TST hours","TRT minutes","oxygen flow","REM minutes only"],"a":"TST hours","why":"PLMI is movements per hour of sleep."},{"q":"PLMI is 20/hr over 5 hours of sleep. Approximately how many PLMs occurred?","choices":["25","50","100","200"],"a":"100","why":"20 x 5 = 100."},{"q":"Why is a raw PLM count not enough by itself?","choices":["The index depends on sleep time","PLMs are PAP pressures","PLMs are percentages","The count must be converted to volts"],"a":"The index depends on sleep time","why":"PLMI normalizes the count to hours of sleep."}]},{"id":"arousal-index","short":"Arousal Index","title":"Arousal Index","tag":"arousal index","unit":"arousals/hour","formula":"Arousal index = arousals / TST hours","concept":"The arousal index expresses how many scored arousals occurred per hour of sleep.","trap":"Do not use all EEG changes; only scored arousals that meet criteria belong in the numerator.","example":["Arousals = 90","TST = 360 min = 6 hr","Arousal index = 15/hr"],"solve":["Count scored arousals","Convert TST to hours","Divide"],"questions":[{"q":"60 arousals over 300 min TST. Arousal index?","choices":["6/hr","10/hr","12/hr","20/hr"],"a":"12/hr","why":"60 / 5 = 12/hr."},{"q":"Arousal index is 18/hr over 5 hours TST. Approximately how many arousals?","choices":["18","36","72","90"],"a":"90","why":"18 x 5 = 90."},{"q":"What denominator is used for PSG arousal index?","choices":["TST hours","TRT minutes","number of apneas","SpO2"],"a":"TST hours","why":"Arousal index is per hour of sleep."},{"q":"Which events belong in the numerator?","choices":["Scored arousals","Every body movement","Every snore","Every PAP leak"],"a":"Scored arousals","why":"Only events meeting arousal criteria are counted."},{"q":"Why can artifact inflate a poorly calculated arousal index?","choices":["Artifact may be mistaken for EEG arousal activity","Artifact changes TST to hours","Artifact changes cm H2O to mmHg","Artifact creates oxygen flow"],"a":"Artifact may be mistaken for EEG arousal activity","why":"Signal quality must be verified before scoring."}]},{"id":"odi","short":"ODI","title":"Oxygen Desaturation Index","tag":"oxygen index","unit":"desaturations/hour","formula":"ODI = qualifying desaturations / sleep or monitoring hours","concept":"ODI summarizes how often qualifying oxygen desaturations occur. The denominator depends on the study/report convention.","trap":"Read whether the denominator is sleep time or monitoring time. Do not assume every oxygen drop is a qualifying desaturation.","example":["Desaturations = 48","Monitoring time = 6 hr","ODI = 8/hr"],"solve":["Count qualifying desaturations","Identify the required denominator","Convert time to hours","Divide"],"questions":[{"q":"40 desaturations over 5 hours. ODI?","choices":["5/hr","8/hr","10/hr","40/hr"],"a":"8/hr","why":"40 / 5 = 8/hr."},{"q":"Which question detail is essential before calculating ODI?","choices":["Which time denominator the report uses","Which PAP mask color was used","Which leg electrode was left","Which room the study occurred in"],"a":"Which time denominator the report uses","why":"ODI denominator may be sleep or monitoring time depending on context."},{"q":"72 desaturations over 6 hours. ODI?","choices":["6/hr","10/hr","12/hr","18/hr"],"a":"12/hr","why":"72 / 6 = 12/hr."},{"q":"Does every SpO2 fluctuation automatically count in ODI?","choices":["No, only qualifying desaturations are counted","Yes, every 1% change counts","Only increases count","Only changes during wake count"],"a":"No, only qualifying desaturations are counted","why":"The event must meet the reporting/scoring definition used."},{"q":"ODI is what kind of value?","choices":["frequency index","pressure","flow rate","impedance"],"a":"frequency index","why":"It is desaturations per hour."}]},{"id":"pressure-support","short":"PS","title":"Pressure Support","tag":"PAP math","unit":"cm H2O","formula":"Pressure support = IPAP - EPAP","concept":"Pressure support is the difference between inspiratory and expiratory pressure in bilevel therapy.","trap":"Subtract EPAP from IPAP. Do not add them and do not use L/min.","example":["IPAP = 16 cm H2O","EPAP = 10 cm H2O","PS = 6 cm H2O"],"solve":["Identify IPAP","Identify EPAP","Subtract EPAP from IPAP","Keep cm H2O as the unit"],"questions":[{"q":"IPAP 18 and EPAP 10. Pressure support?","choices":["8 cm H2O","10 cm H2O","18 cm H2O","28 cm H2O"],"a":"8 cm H2O","why":"18 - 10 = 8 cm H2O."},{"q":"IPAP 14 and EPAP 8. Pressure support?","choices":["4 cm H2O","6 cm H2O","8 cm H2O","22 cm H2O"],"a":"6 cm H2O","why":"14 - 8 = 6 cm H2O."},{"q":"Which unit belongs to pressure support?","choices":["cm H2O","L/min","mmHg","%"],"a":"cm H2O","why":"PAP pressures use cm H2O."},{"q":"Pressure support is 5 and EPAP is 9. What IPAP produces that support?","choices":["4","9","14","45"],"a":"14","why":"IPAP = EPAP + PS = 9 + 5 = 14."},{"q":"What is the most common setup error in pressure-support math?","choices":["Adding IPAP and EPAP instead of subtracting","Converting minutes to hours","Using TST","Counting apneas"],"a":"Adding IPAP and EPAP instead of subtracting","why":"PS is the difference between IPAP and EPAP."}]},{"id":"oxygen-flow","short":"O2 Flow","title":"Oxygen Flow and Delivery","tag":"oxygen units","unit":"L/min","formula":"Oxygen flow is documented in L/min unless a question specifies FiO2/another setup","concept":"Sleep technologists must keep oxygen source, delivery device, ordered flow, FiO2, and patient SpO2 separate.","trap":"Do not mix L/min, percent, mmHg, and cm H2O.","example":["Order: 2 L/min oxygen","Source: wall oxygen","Device: nasal cannula","Patient response: SpO2 in percent"],"solve":["Identify the source","Identify the device","Identify the flow or FiO2","Identify the patient response separately"],"questions":[{"q":"Which unit is most appropriate for low-flow oxygen delivered by nasal cannula?","choices":["L/min","cm H2O","kΩ","Hz"],"a":"L/min","why":"Low-flow oxygen is commonly charted in liters per minute."},{"q":"Which value is the patient response rather than the oxygen dose?","choices":["SpO2 94%","2 L/min","nasal cannula","wall oxygen"],"a":"SpO2 94%","why":"SpO2 is the measured patient oxygen saturation."},{"q":"Which item describes the source?","choices":["Oxygen cylinder","3 L/min","SpO2 92%","nasal cannula"],"a":"Oxygen cylinder","why":"The cylinder/tank is where oxygen comes from."},{"q":"Which item describes the delivery device?","choices":["Nasal cannula","2 L/min","FiO2 0.28","SpO2 95%"],"a":"Nasal cannula","why":"The cannula is the interface."},{"q":"Which unit would be wrong for oxygen flow?","choices":["cm H2O","L/min","liters per minute","lpm"],"a":"cm H2O","why":"cm H2O is a PAP pressure unit."}]},{"id":"o2-co2-units","short":"O2/CO2 Units","title":"Oxygen and CO2 Units","tag":"unit trap","unit":"mixed","formula":"SpO2/SaO2 = %; PaO2/PaCO2/EtCO2/TcCO2 = mmHg; PAP = cm H2O; O2 flow = L/min","concept":"Many best-answer questions can be solved by matching the measurement to its correct unit before doing any arithmetic.","trap":"Do not mix saturation, partial pressure, PAP pressure, flow, and frequency units.","example":["SpO2 92% = saturation","PaCO2 48 mmHg = arterial CO2 pressure","CPAP 10 cm H2O = airway pressure","Oxygen 2 L/min = flow"],"solve":["Name the measurement","Ask whether it is saturation, pressure, flow, frequency, or resistance","Choose the matching unit"],"questions":[{"q":"Which unit belongs to PaCO2?","choices":["mmHg","%","cm H2O","L/min"],"a":"mmHg","why":"PaCO2 is a partial pressure."},{"q":"Which unit belongs to SpO2?","choices":["%","mmHg","cm H2O","kΩ"],"a":"%","why":"SpO2 is oxygen saturation."},{"q":"Which unit belongs to CPAP pressure?","choices":["cm H2O","mmHg","L/min","Hz"],"a":"cm H2O","why":"PAP pressures are expressed in cm H2O."},{"q":"Which unit belongs to oxygen flow?","choices":["L/min","cm H2O","% only","µV"],"a":"L/min","why":"Low-flow oxygen delivery is commonly charted in liters per minute."},{"q":"Which pair is correctly matched?","choices":["EtCO2 - mmHg","SpO2 - cm H2O","CPAP - L/min","Impedance - %"],"a":"EtCO2 - mmHg","why":"End-tidal CO2 is commonly measured in mmHg."}]},{"id":"sensitivity","short":"Sensitivity","title":"Sensitivity and Display Size","tag":"instrument math","unit":"µV/mm","formula":"Sensitivity = input voltage / deflection","concept":"Sensitivity describes how many microvolts are represented per millimeter of display deflection in this simplified teaching model.","trap":"Lower µV/mm means the same signal appears taller. Higher µV/mm means it appears shorter.","example":["Signal = 50 µV","Sensitivity = 10 µV/mm","Deflection = 5 mm"],"solve":["Use compatible units","Deflection = signal µV / sensitivity µV/mm","Sensitivity = signal µV / deflection mm"],"questions":[{"q":"A 50 µV signal is displayed at 10 µV/mm. How tall is the deflection?","choices":["2 mm","5 mm","10 mm","50 mm"],"a":"5 mm","why":"50 / 10 = 5 mm."},{"q":"A 40 µV signal makes an 8 mm deflection. What is sensitivity?","choices":["5 µV/mm","8 µV/mm","32 µV/mm","48 µV/mm"],"a":"5 µV/mm","why":"40 / 8 = 5 µV/mm."},{"q":"If sensitivity changes from 10 µV/mm to 5 µV/mm, the same signal appears how?","choices":["Twice as tall","Half as tall","The same height","It disappears"],"a":"Twice as tall","why":"Fewer µV per mm makes the waveform larger on the display."},{"q":"Which unit belongs to this sensitivity model?","choices":["µV/mm","L/min","cm H2O","events/hr"],"a":"µV/mm","why":"It relates voltage to display deflection."},{"q":"Does changing sensitivity change the patient's true EEG voltage?","choices":["No, it changes display scaling","Yes, it doubles brain voltage","Yes, it changes frequency","Yes, it changes impedance"],"a":"No, it changes display scaling","why":"Sensitivity changes the display, not the underlying physiologic signal."}]},{"id":"frequency","short":"Frequency","title":"Frequency and Period","tag":"signal math","unit":"Hz","formula":"Frequency = cycles / seconds; period = 1 / frequency","concept":"Frequency tells how many cycles occur each second. Period tells the time for one cycle.","trap":"Do not confuse amplitude with frequency.","example":["20 cycles occur in 4 seconds","Frequency = 20 / 4 = 5 Hz","Period = 1 / 5 = 0.2 second"],"solve":["Count cycles","Measure seconds","Divide cycles by seconds","For period, use 1/frequency"],"questions":[{"q":"24 cycles occur in 3 seconds. Frequency?","choices":["6 Hz","8 Hz","12 Hz","24 Hz"],"a":"8 Hz","why":"24 / 3 = 8 cycles per second."},{"q":"A 10 Hz wave has what period?","choices":["0.1 s","1 s","10 s","100 s"],"a":"0.1 s","why":"Period = 1 / 10 = 0.1 second."},{"q":"Which unit is frequency?","choices":["Hz","µV","mmHg","L/min"],"a":"Hz","why":"Hertz means cycles per second."},{"q":"A wave has 6 cycles in 2 seconds. Frequency?","choices":["2 Hz","3 Hz","6 Hz","12 Hz"],"a":"3 Hz","why":"6 / 2 = 3 Hz."},{"q":"Which property describes waveform height?","choices":["Amplitude","Frequency","Period","Sampling rate"],"a":"Amplitude","why":"Amplitude is signal size; frequency is cycles per second."}]},{"id":"ohms-law","short":"Ohm's Law","title":"Ohm's Law Basics","tag":"electrical math","unit":"V, A, Ω","formula":"V = I x R; I = V / R; R = V / I","concept":"Ohm's law relates voltage, current, and resistance. Sleep technology questions often test the relationship and units rather than complex electronics.","trap":"Keep volts, amperes, and ohms straight. Do not confuse impedance with signal amplitude.","example":["V = 10 V","R = 5 Ω","I = 10 / 5 = 2 A"],"solve":["Identify the unknown","Choose the rearranged formula","Keep units consistent","Calculate"],"questions":[{"q":"V = 12 V and R = 6 Ω. Current?","choices":["2 A","6 A","18 A","72 A"],"a":"2 A","why":"I = V / R = 12 / 6 = 2 A."},{"q":"I = 2 A and R = 5 Ω. Voltage?","choices":["2.5 V","7 V","10 V","25 V"],"a":"10 V","why":"V = I x R = 2 x 5 = 10 V."},{"q":"V = 20 V and I = 4 A. Resistance?","choices":["4 Ω","5 Ω","16 Ω","80 Ω"],"a":"5 Ω","why":"R = V / I = 20 / 4 = 5 Ω."},{"q":"Which unit belongs to resistance?","choices":["Ω","V","A","Hz"],"a":"Ω","why":"Ohms measure resistance."},{"q":"Which formula solves for current?","choices":["I = V / R","I = V x R","I = R / V","I = V + R"],"a":"I = V / R","why":"Rearrange V = I x R."}]},{"id":"ten20","short":"10-20","title":"10-20 Measurement Math","tag":"electrode math","unit":"cm or mm","formula":"Distance at a percentage = total measurement x percentage","concept":"The 10-20 system uses proportions of measured head distances. Exam questions may ask for a percent of a given circumference or arc.","trap":"Convert percentages to decimals and use the specific measurement named in the question.","example":["Measured arc = 36 cm","20% position = 36 x 0.20 = 7.2 cm"],"solve":["Identify the measured distance","Convert the percent to decimal","Multiply","Keep the same length unit"],"questions":[{"q":"20% of a 40 cm arc is how far?","choices":["4 cm","8 cm","12 cm","20 cm"],"a":"8 cm","why":"40 x 0.20 = 8 cm."},{"q":"10% of a 38 cm distance is how far?","choices":["1.9 cm","3.8 cm","7.6 cm","38 cm"],"a":"3.8 cm","why":"38 x 0.10 = 3.8 cm."},{"q":"Which decimal equals 20%?","choices":["0.02","0.20","2.0","20.0"],"a":"0.20","why":"Percent / 100 = decimal."},{"q":"A 42 cm arc requires a 10% measurement. Distance?","choices":["2.1 cm","4.2 cm","8.4 cm","10 cm"],"a":"4.2 cm","why":"42 x 0.10 = 4.2 cm."},{"q":"Why must the head be measured rather than electrode positions simply eyeballed?","choices":["The system is proportional to the individual head","The EEG changes every centimeter","PAP pressure depends on head size","SpO2 requires it"],"a":"The system is proportional to the individual head","why":"10-20 placement is based on measured proportions."}]}]};})(typeof window!=='undefined'?window:globalThis);
